customCSS:
body {
    font-family: 'Inter', sans-serif;
}

body.dark {
    background-color: #0f1117 !important;
}

a, .link {
    color: #00BAFF !important;
}

.btn-primary, .btn-primary:hover {
    background-color: #00BAFF !important;
    border-color: #00BAFF !important;
    color: #000000 !important;
}

.monitor-name {
    font-weight: 600;
}

.hero-text, h1 {
    color: #00BAFF !important;
}

.status-bar-bg {
    background-color: #1a1f2e !important;
}

.p-3.shadow-box.big-padding.period-pill {
    border-left: 4px solid #00BAFF;
}

/* Incident box */
.shadow-box.alert.incident.bg-primary {
    background-color: #1a1f2e !important;
    border: 1px solid #00BAFF !important;
    color: #ffffff !important;
}

.shadow-box.alert.incident.bg-primary .alert-heading,
.shadow-box.alert.incident.bg-primary strong,
.shadow-box.alert.incident.bg-primary .content {
    color: #ffffff !important;
}

.shadow-box.alert.incident.bg-primary .form-text {
    color: #aaaaaa !important;
}
